  "五段動詞用お段加う、一段用よう，する變しよう、くる變こよう。本課對照主體：{僕|ぼく}が…しよう是自告奮勇，…しようか可提議協助；不能當成命令對方獨自行動。",
  "動詞ない形接で，可表示不做前項而做後項；複習請求用法，進一步分辨「沒有按就看」與「看不懂而困擾」。本課的ないで不是因果的なくて。",
  "否定ない改為なくて，可連接原因或並列。本課以原因用法對照te-reason：不是把なくて一律翻成「不做就…」，而是看後面是否為困難、感受或結果。",
  "でしょう可表示推測，也能詢問共有資訊；口語でしょ保留確認功能。對方仍可修正記憶，不把尋求認同當成內容已證實。",
  "じゃない是ではない的口語形式；升調或上下文可能用來詢問「不是…嗎」。不只抓ない就判定否定，要連同回應判斷。本課以原否定形式的清單ID對照，實際語氣仍靠上下文。",
