  "普通形接ようだ，名詞用のようだ、な形容詞用なようだ；也可表相似。本課用具體跡象支持推斷，和直接確認相區分，並對照較口語的みたい。",
  "名詞直接接みたい，可說像某物；普通形接みたい也能依線索推測。它不等於確認事實，必須看說話者是在比外形，還是判斷背後情況。",
  "普通形接し可列舉理由，也能在句末留下未明說的結論。複習已學的し，本課注意它沒有保證理由已列完；要用後續問答確認具體決定。",
