  "乙說「{少|すこ}しなら{読|よ}める」並補充「{全部|ぜんぶ}はわからない」；不能只聽到{読|よ}める就判定全部理解。",
  "乙讀出「この{先|さき}の{橋|はし}は{危険|きけん}です」；這是告示的危險提醒。",
  "甲說「{別|べつ}の{道|みち}を{探|さが}そう」，決定找別條路；乙再表示願意帶路。",
  "動詞た形接ら可表示如果或某件事發生之後；否定條件用なかったら。對話中的{降|ふ}ったら與{降|ふ}らなかったら是兩種不同的天氣假設，不是報告已經下雨。",
  "普通形或名詞接なら，表示如果是某種情況，就提出建議或判斷。「{山|やま}に{行|い}くなら」先接住登山這個計畫，再說需要什麼，不表示已經抵達山上。",
  "{降|ふ}らなかったら。 是已經沒下雨嗎？",
  "{山|やま}に{行|い}くなら。 後面通常接什麼？",
