  "{寒|さむ}くなったら、すぐ{戻|もど}ろう。 說明什麼行動條件？",
  "甲說「{雨|あめ}が{降|ふ}ったら、{洞窟|どうくつ}で{休|やす}もう」；登山是沒有下雨時的另一個計畫。",
  "乙接著登山的前提說「{上着|うわぎ}が{必要|ひつよう}だね」，指出要準備外衣。",
  "甲說「{寒|さむ}くなったら、すぐ{戻|もど}ろう」，把變冷與立刻折返連在一起。",
