  '「{安心|あんしん}して」由「{安心|あんしん}する」變化而來，表示放心地做某事；「{任|まか}せたまえ」用較古雅的命令表現請對方交給自己處理。',
  '「{貫|つらぬ}こう」是「{貫|つらぬ}く」的意向形，表示說話者提議貫徹或穿過某事物。',
  '「{月|つき}のように」用「ように」作比喻；「{永遠|えいえん}なれ」以文語命令形表達祝願，近似「{永遠|えいえん}であれ」。',
  '「{近|ちか}づけば{近|ちか}づくほど」是ば形搭配「ほど」，表示越……越……；「{真実味|しんじつみ}が{増|ま}す」表示真實感增強。',
  '「シャルロットが」以「が」標示動作主體；「{報道|ほうどう}します」是「{報道|ほうどう}する」的禮貌形，表示將進行報導。',
  '「{行|い}こう」是「{行|い}く」的意向形，表示一起前往；「{弾|たま}は」提出子彈作為主題；「{装填|そうてん}した」表示已裝好彈藥。',
  '「{風|かぜ}が」指出風作為主題；「{風|かぜ}が{立|た}つ」表示風起；句尾「ぞ」是男性口語的強調語氣。',
  '「{消|き}え{失|う}せろ」是「{消|き}え{失|う}せる」的命令形，帶強烈、粗獷的驅逐語氣。',
  '「{武器|ぶき}を」以「を」標示動作對象；「{捨|す}てろ」是「{捨|す}てる」的命令形，用於強硬要求對方丟下武器。',
  '「{投降|とうこう}する」的命令形是「{投降|とうこう}しろ」，語氣直接強硬，要求對方停止抵抗。',
  '「ようこそ」是歡迎用語；「{千織屋|ちおりや}へ」以「へ」指出歡迎前往的地點，千織屋是店名。',
  '「{手伝|てつだ}って」是「{手伝|てつだ}う」的て{形|けい}，可作口語請求；說話者省略了「ください」。',
  '「ファッションは」以「は」提出主題；「{私|わたし}が{定義|ていぎ}する」以「が」標示主體，說明由我決定時尚的定義。',
  '「{心得|こころえ}る」表示明白、領會；「{心得|こころえ}た」用過去形回應，表示已經理解。',
  '「{剣|けん}よ」用「よ」呼喚劍；「{出|い}でよ」是文語動詞「{出|い}づ」的命令形，要求其出現。',
  '「{妖魔|ようま}め」以「め」加上輕蔑語氣；「{立|た}ち{去|さ}れ」是「{立|た}ち{去|さ}る」的命令形，要求對方離開。',
  '{元素|げんそ}スキル・1',
  '「モチロン」是「もちろん」的強調寫法；「{手伝|てつだ}ったげる」是「{手伝|てつだ}ってあげる」的口語縮約，表示願意替對方幫忙。',
  '「{働|はたら}きなさい」由「{働|はたら}く」的連用形加「なさい」構成，是帶指示語氣的命令；句首「さ」催促對方開始行動。',
  '「{口封|くちふう}じ」指讓人閉嘴或阻止消息外傳；「{任|まか}せた」表示把事情交給對方；「からね」帶提醒與確認語氣。',
  '「{代理|だいり}{決闘|けっとう}の{依頼|いらい}」以「の」連接委託內容；句尾「か」提出疑問，確認對方是否來委託代理決鬥。',
  '「{影|かげ}を」用「を」標示動作對象；「{討|う}つ」表示攻擊或討伐，辭書形直接用作短促宣言。',
  '「{潔白|けっぱく}を{証明|しょうめい}する」是動詞辭書形修飾「{時|とき}」；「{時|とき}だ」表示現在正是採取該行動的時候。',
  '「{準備|じゅんび}{万端|ばんたん}だ」簡短宣告都已準備妥當；「{出発|しゅっぱつ}しよう」是「{出発|しゅっぱつ}する」的意向形，邀請一起出發。',
  '「{飛|と}べ」是「{飛|と}ぶ」的命令形，短促地要求對方飛出去。',
  '「{頼|たの}む」表示請求或拜託；句尾「よ」加強呼喚語氣，「コレアンバー」是直接呼叫的名稱。',
  "{行|い}こう是{行|い}く的意志形，加か提出邀請或商量，不是過去式。",
  "{下|くだ}す是動詞辭書形，在此宣告將採取的行動；{下|くだ}せ才是命令形。",
  "しやがれ是する加上やがる的命令形，帶粗魯、挑釁語氣；おとなしく表示老實、安分地。",
  "{風邪|かぜ}ひく省略了{風邪|かぜ}をひく的を；動詞辭書形加な表示禁止，よ在此加強提醒。",
  "{行|い}こう提出行動邀請；{時間|じかん}は以は提示話題，句尾よ提醒對方時間有限。",
