  '「{最善|さいぜん}」表示最好的做法；「{尽|つ}くそう」是「{尽|つ}くす」的意向形，表示提議竭盡全力。',
  '「{逃|に}げ{場|ば}」指逃跑的地方；「は」提出話題，否定句「ない」加「ぞ」強調沒有退路。',
  '「{判決|はんけつ}から」以「から」表示逃離的起點；「{逃|のが}れられない」是「{逃|のが}れる」的可能形否定，表示無法逃脫。',
  '「{何|なに}か」表示某件事或某種東西；「{依頼|いらい}がある」提出有委託；句尾「のか」用於口語確認或詢問。',
  '「{手加減|てかげん}ナシ」表示不留情面；「だぜ」是男性口語的斷定與強調語氣。',
  '「{耐|た}えられる」是「{耐|た}える」的可能形；「かな」表示說話者自問或帶有不確定的詢問。',
  '「{一儲|ひともう}け」讀作「ひともうけ」，表示賺一筆；「しに{行|い}く」以「する」連用形加「に{行|い}く」表示去做某事。句尾「の」是多莉的女性口語語氣。',
