  '「{私|わたし}は{学校|がっこう}へ{行|い}きます。」的「へ」怎麼唸？',
  '「{私|わたし}は{学生|がくせい}です。」を{否定文|ひていぶん}にしてください。',
  '「{私|わたし}は{昨日|きのう}、{銀行|ぎんこう}へ{行|い}きました。」的「{行|い}きました」是什麼形？',
  '「{私|わたし}は{寝|ね}ます。」を{過去|かこ}の{肯定文|こうていぶん}と{否定文|ひていぶん}にしてください。',
  '「{私|わたし}は{働|はたら}きます。」を{否定文|ひていぶん}にしてください。',
  '「{字引|じびき}」現在通常怎麼說？',
  '「{辞書形|じしょけい}」是字典上的形式，也是動詞的基本形。從ます形變過來：①五段動詞把ます前的「い{段|だん}」音換成「う{段|だん}」（{書|か}きます→{書|か}く、{飲|の}みます→{飲|の}む、{話|はな}します→{話|はな}す、{待|ま}ちます→{待|ま}つ、{泳|およ}ぎます→{泳|およ}ぐ、{買|か}います→{買|か}う）；②一段動詞把「ます」換成「る」（{食|た}べます→{食|た}べる）；③不規則：{来|き}ます→{来|く}る、します→する。單字表裡列的動詞就是辭書形。',
  '「{弱|よわ}いから」是理由；「なめられる」是「なめる」（瞧不起）的被動形；句尾「んだ」（のだ）帶說明、自省的語氣，整句是「就是因為弱才會這樣」。',
  '「{弱|よわ}いからなめられるんだ」的「なめられる」是什麼形？',
  '「{住|す}んでいます」是現在的狀態（住在）；「{住|す}んでいました」是過去的狀態（以前住在）。',
  '「{住|す}んでいます」和「{住|す}んでいました」有什麼不一樣？',
  '「{十一時|じゅういちじ}ごろ{寝|ね}ます」的「ごろ」是什麼意思？',
  '「{暑|あつ}い」是天氣、氣溫熱；「{熱|あつ}い」是東西、水燙。',
