  'い形容詞的過去式：把最後的「い」換成「かった」，再加「です」：{暑|あつ}い→{暑|あつ}かったです。否定過去是「くなかったです」：{暑|あつ}くなかったです。特殊：「いい」的過去是「よかったです」，否定是「よくなかったです」。',
