  "倒過來說「某個東西在哪裡」：把東西放在は前面，場所放在です前面。問「在哪裡」就是「N はどこですか」，回答時把「どこ」換成場所。",
  "「請〜」，用て形加「ください」，是最基本的拜託、請求的說法。要更客氣可以在前面加「すみませんが」；後面加「ね」語氣較柔和。",
  "「可以〜」：て形加「もいいです」。問許可用「〜てもいいですか」，答應說「はい、いいですよ」，不答應說「いいえ、いけません」或比較委婉的「すみません、ちょっと…」。",
  "「不可以〜」：て形加「はいけません」，用來說規則、禁止的事。口語常說成「〜ちゃいけません」（第 2 階段會學）。回答「〜てもいいですか」被拒絕時，說「いいえ、いけません」。",
  "「請不要〜」：ない形加「でください」，是拜託對方不要做某事，比「〜てはいけません」（不可以）溫和。",
  "「為別人做某事（我做給對方）」：て形加「あげます」。有時會讓對方覺得「我幫了你」，所以對長輩、上司通常改用「〜ましょうか」（我來〜好嗎）提出幫忙比較有禮貌。",
  "這裡的は是主題助詞，讀わ；字面は與助詞實際發音要分開。",
  "名詞後加のはず；な形容詞才接なはず，不能把接續混用。",
  "しなさい要求準備；另外兩個分別是禁止與持續／狀態描述，意思不同。",
  "すら配合{出|で}ない，指出連聲音這個程度都做不到；不是喜好或命令。",
  "「{壊|こわ}す{時|とき}」以動詞辭書形修飾時間；「でしょ？」邀請對方認同。「しびれる」在口語也可表示興奮、過癮，整句語氣隨意而自信。",
  "「バンバーン」是模仿聲響的擬聲詞；「{花火|はなび}の{始|はじ}まり」以名詞說明開始的事。「ですよ」帶告知語氣，整句活潑。",
  "「からの」表示委託來源；「{始|はじ}めよう」是意志形，可作自我決定或號召，語氣冷靜俐落。",
  "「{見|み}ておけ」是「ておく」的命令形，要求先看清楚；「{誰|だれ}にも{止|と}められない」用可能形否定強調無人能阻止，語氣強勢。",
  "「{彷徨|さまよ}う」修飾「{魂|たましい}」；句尾「を」後省略動詞，留下祈願或宣告的片語感，語氣莊嚴。",
  "「なら」提出條件；「{従|したが}います」是禮貌承諾，句尾「にゃん」加入貓咪口吻，語氣恭順又可愛。",
  "「{哀|あわ}れな」修飾「{者|もの}たち」；助詞「を」標出「{導|みちび}く」的對象。「ます」是禮貌形式，省略號讓語氣顯得莊嚴而未說完。",
  "「どんな」詢問種類；「{来|き}てくれる」帶有對方來訪使自己受惠的語感；「のか」把疑問內容包進句子，接「{楽|たの}しみです」表期待，語氣親切。",
  "「たら」提出條件；「{払戻|はらいもど}されちゃう」是「{払戻|はらいもど}されてしまう」的口語縮約，表示款項會被退回。「よ」加強提醒，語氣輕快。",
  "「やっつけに{行|い}く」是「去做某事」的句型；「んだよね？」帶確認語氣，整句口語而友善。",
  "「こっちにおいで」是親近的邀請；「{私|わたし}を{温|あたた}かくして」省略了執行者，句尾て形留下未完語感，省略號把句子切成斷續的片段。",
  "「{賢明|けんめい}」是な形容詞，以「な」修飾「{選択|せんたく}」；句尾「です」禮貌而克制，像簡短評語。",
  "「お{待|ま}たせ」省略了後續說明，是「讓你久等了」的招呼；「{始|はじ}まるよ」告知即將開始；句尾「～」標示拉長音，語氣雀躍。",
  "「てやる」表示說話者替別人做事，可能帶居高臨下的語感；「{片付|かたづ}ける」也可泛指處理妥當，單句不指定對象，語氣從容。",
  "「{広|ひろ}がる{前|まえ}に」表示趁擴散之前；「しなければなりません」表義務，正式且斷然，符合說明規則的語氣。",
  "「{新|あら}たな」修飾「{夢|ゆめ}」；「{旅立|たびだ}つ{時間|じかん}だ」表示時機已到。句尾「わ」帶柔和的女性口吻，整句像平靜地作出宣告。",
  "「{閉|と}じて」連接後續動作；「{出|で}かけてみる」是試著出門看看。「ましょうか」以禮貌形式提出共同提議，語氣溫和。",
  "「{絶対|ぜったい}に」加強否定「{外|はず}さない」，表達堅定自信；「ピョン」是兔子跳躍的擬態音，讓語氣帶點可愛反差。",
  "「{勝|か}てる」是可能形；「だけ」表示只有。「んだから」補充理由並加強情緒，語氣熱烈、帶有親密鼓勵。",
  "「{作|つく}れる」是「{作|つく}る」的可能形；「かな」表示自問，語氣期待而親切。",
  "「つもり」表示打算；「けど」先交代計畫，再接隨意邀請「{見|み}に{来|く}る？」。語氣親近。",
  "「{時|とき}を{経|へ}て」表示經過一段時間；「{降臨|こうりん}した」是完成的過去形。「わらわ」與「のじゃ」帶古風、自命不凡的語氣。",
  "「では」承接前文並轉入下一步；「{向|む}かいましょう」是禮貌的共同提議，語氣俐落。",
  "「{指導|しどう}が{必要|ひつよう}な{子|こ}」以「{必要|ひつよう}な」修飾「{子|こ}」；「どこにいるのかしら」是帶女性語感的自問，口吻自信又好奇。",
  "「は」提出話題，「{好|す}き」是な形容詞；句中沒有「か」，靠問號（口語句尾上揚）形成問句；省略號讓語氣顯得遲疑。",
  "「わざわざ」表示特地；「{出向|でむ}く」是親自前往。「{必要|ひつよう}ありますか」省略了「が」，仍是禮貌問句，帶些質疑。",
  "「どんな{味|あじ}がする」詢問味道；「かのう」是古風自問語尾，搭配重複的「{味|あじ}」與笑聲，呈現戲謔又陰森的口吻。",
  "「{存分|ぞんぶん}に」表示盡情地；「{楽|たの}しんでおかないと」省略「いけない」，是「得先好好享受才行」的口語說法，語氣像自我提醒。",
