  "「{知識|ちしき}を」提出知識這個對象，後面省略分享等動詞；「にも」結合に與も，表示也給你。",
  "「{力|ちから}になる」表示成為助力；「なれる」是可能形；句尾「ように」省略後面的願望表達，意思是希望能幫上忙。",
  "「{吸引|きゅういん}テスト」以名詞修飾另一名詞；「{開始|かいし}」單獨放在句尾作省略「{開始|かいし}する」的號令，常見於實驗或設備操作。",
  "「{超|ちょう}」作前綴，表示超越一般程度；「{拡散|かくさん}」是向外散開；「{形態|けいたい}」是形式或狀態。整句以名詞片語作簡短宣告。",
  "「{食材|しょくざい}は」提出主題；「{全部|ぜんぶ}」表示全部；「{持|も}った」是{持|も}つ的過去形，在這裡表示已經帶好。句尾よ提醒對方。",
  "「{料理|りょうり}の{時間|じかん}」用の連接兩個名詞；だ表示判斷，句尾よ告知對方現在到了料理的時間。",
  "「{師匠|ししょう}の{技|わざ}」是師父的招式；「{食|く}らう」在戰鬥語境表示承受攻擊。「{食|く}らいなさい」由ます形去掉ます加なさい，帶強烈命令語氣。",
  "{元素|げんそ}{爆発|ばくはつ}·3",
  "「{雨垂れ|あまだれ}」是滴落的雨水；「{石|いし}をも」的も強調連石頭也能穿透。「{穿|うが}つ」表示鑿穿，整句以諺語說明持續努力能產生成果。",
  "「この{剣|けん}は」提出眼前這把劍；「{分|わ}かる」表示明白。句尾かい是口語問法，這裡在戰鬥中帶挑戰意味。",
  "「{詩|し}よ」的よ是在呼喚詩；「{錦|にしき}」是華美的織物。「となれ」由と標示變化結果，加なる的命令形なれ，帶詩意宣告語氣。",
  "「{皇女|こうじょ}の{名|な}のもとに」表示以皇女的名義或權威行事；這裡省略後面的動作，是莊重的宣告。名在此讀な。",
  "「{姿|すがた}を{見|み}せる」表示現身；「{見|み}せよ」是{見|み}せる的書面語命令形，較口語的{見|み}せろ莊重。オズ是呼喚的對象。",
  "「{黒|くろ}き」是黑色的文語說法，修飾翼；よ在這裡呼喚翼。「{昼夜|ちゅうや}」指白天與夜晚；「{切|き}り{裂|さ}きなさい」由{切|き}り{裂|さ}く的ます形去掉ます加なさい，表示命令。",
  "「いつでも」表示任何時候都可以；「{出発|しゅっぱつ}できる」是{出発|しゅっぱつ}する的可能表達，說明已經能夠出發。",
  "「いざ」是準備採取行動時的號召；「{勝負|しょうぶ}」單獨作戰鬥宣告，省略後面的動詞。",
  "「{剣|けん}に」用に標示誓言所寄託的對象；「{誓|ちか}う」表示發誓，辭書形在這裡作當場宣告。",
  "「クレーが」用が指出提供幫助的人；「{手伝|てつだ}う」表示幫忙，句尾よ告知對方自己的打算。",
  "「{弾|はじ}けろ」是{弾|はじ}ける的命令形；這裡結合爆彈情境表示炸開，不是他動詞的把某物彈走。",
  "「{火力|かりょく}」表示攻擊或燃燒的力量；「{全開|ぜんかい}」表示全部開啟。整句以名詞片語宣告全力出擊。",
  "「あたしに」指出交託的對象；「{任|まか}せなさい」由{任|まか}せる的ます形去掉ます加なさい，帶要求對方交給自己處理的語氣。",
  "「{甘|あま}く{見|み}る」表示輕視；「{見|み}ないで」用ないで要求對方不要做這個動作，整句要求別小看自己。",
  "{元素|げんそ}スキル·6",
  "「{反省|はんせい}しなさい」由{反省|はんせい}する的ます形去掉ます加なさい，要求對方反省。「{酔|よ}っぱらいさん」是帶さん的呼稱，這裡帶揶揄語氣。",
  "ている省去い成てる；不是過去形，也不是不想愛的否定願望。",
  "「{一緒|いっしょ}に」表示一起；「{探索|たんさく}しよう」是探索する的意向形，邀請對方共同探索。",
  "「{咲|さ}け」是咲く的命令形；在戰鬥語境以開花的動作作簡短號令。",
  "「{偉業|いぎょう}を」是要見證的對象；「{見届|みとど}けよ」是{見届|みとど}ける的書面語命令形，要求對方看到事情的結果。",
  "「あんた」是你，比あなた隨意，須留意關係與場合；「{信|しん}じる」表示相信，句尾よ傳達自己的態度。",
  "「{全部|ぜんぶ}」表示全部；「{返|かえ}してやる」由{返|かえ}す的て形加やる，在這裡以粗獷語氣宣告把攻擊還給對方。",
  "「よく」在這裡表示仔細；「{見|み}ておけ」由見る的て形加おく，再用命令形おけ，要求對方仔細看著並記住。",
  "「オレ」是較粗獷的第一人稱；が強調由我行動；「{行|い}く」用辭書形宣告接下來要去。",
  "「{来|く}るな」由動詞辭書形加な，表示強烈禁止；ッ保留原來源的收尾記法。",
