  "「{戻|もど}れ」是「{戻|もど}る」的命令形，要求回到原處。ラ行五段動詞把語尾「る」變成「れ」。",
  "「{聞|き}き{給|たま}え」是帶莊重語氣的命令表達；「ここにて」相當於在此，「{命|めい}ずる」表示下令。",
  "「また」表示又、再次；「{新|あたら}しい」修飾「{仕事|しごと}」。句尾省略判斷詞，以口語詢問是否又有新的任務。",
  "「{許|ゆる}さない」是「{許|ゆる}す」的否定形，可表示不允許，也可表示不原諒。",
