  "「ご{安心|あんしん}を」在「{安心|あんしん}」前加敬語接頭語「ご」，並省略「ください」等後續部分，用來安撫對方。",
  "「{深海|しんかい}」指很深的海域；「の」連接名詞，「{加護|かご}」指守護、庇佑。",
  "「{寝|ね}てもいい」由て形接「もいい」，表示允許睡覺；句尾「か」詢問許可，屬普通體說法。",
  "「{捕|つか}まる」表示被抓住；否定形「{捕|つか}まらない」表示不會被抓到，句尾「ぞ」加強斷言。",
  "「{出|で}てこい」由「{出|で}る」的て形接「{来|く}る」的命令形，要求對方向說話者這裡出現。",
  "「はいはーい」拉長回應的聲音，帶輕鬆語氣；「{呼|よ}んだ？」用過去形詢問對方是否剛叫了自己。",
  "「{失礼|しつれい}」可以單獨作為打擾、先行致歉時的簡短招呼，完整說法常接「します」。",
  "「{退|ど}いてくれる？」用て形接「くれる」的疑問形式，請對方為自己讓路；「ごめん」與「ちょっと」讓請求較緩和。",
  "「{承知|しょうち}した」表示已了解；「{立|た}っていればいい」用條件形表示保持站立即可，句尾「のか」確認做法。",
  "「{命|めい}ずる」表示下命令，是帶莊重語氣的動詞說法；此處以辭書形宣告下令。",
  "「{従|したが}え」是「{従|したが}う」的命令形；「{律令|りつりょう}に」以「に」標示應當遵從的規則、命令。",
  "「さあ」催促開始行動；「{行|い}こう」是「{行|い}く」的意志形，用來邀請一起出發。「{相棒|あいぼう}」指一起行動的搭檔。",
  "「{言|い}い{逃|のが}れ」表示找藉口逃避責任；「させない」是使役形的否定，表示不允許對方這麼做。",
  "「{罪|つみ}を{認|みと}める」表示承認罪行；「{認|みと}めろ」是一段動詞「{認|みと}める」的命令形。",
  "「お{邪魔|じゃま}する」是進入別人的空間或參與活動時的客氣說法；句尾「ね」讓語氣親近。",
  "「じっと」表示安靜不動；「してて」是「していて」的口語縮略，請對方維持不動的狀態。",
  "「{力|ちから}を{抜|ぬ}く」表示放鬆、不再用力；「リラックスするのよ」以說明、叮嚀的語氣要求對方放鬆。",
  "「{見|み}てて」是「{見|み}ていて」的口語縮略；「てくれ」要求對方為自己做某事，句尾「よな」加強提醒。",
