"乙否定圓屋頂建築，改指細的、名叫ひかり的信號塔。",
"複習ます形去ます接やすい或にくい，描述容易或不容易。{外|はず}れやすい是容易脫落，並不是容易固定；新知在裝備搭配與兩項條件交叉核對。",
